import{_ as a,o as t,c as o,ap as r}from"./chunks/framework.Dv1_Li4I.js";const u=JSON.parse('{"title":"Reactant integration","description":"","frontmatter":{},"headers":[],"relativePath":"reactant.md","filePath":"reactant.md","lastUpdated":null}'),i={name:"reactant.md"};function n(d,e,c,s,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="Reactant-integration" tabindex="-1">Reactant integration <a class="header-anchor" href="#Reactant-integration" aria-label="Permalink to &quot;Reactant integration {#Reactant-integration}&quot;">​</a></h1><p>Reactant is an optional compiler backend, not a dependency of native ReactiveKernels. The reviewed surface starts with scalar and batched distribution kernels, then the Eight Schools and MNIST PPL models, followed by compiled automatic differentiation.</p><p>The same <code>PreparedKernel</code> or <code>PreparedADKernel</code> boundary is traced; Reactant does not introduce a second model language. A Reactant path is supported only where the corresponding primal kernel compiles, and unsupported traced storage or control fails closed.</p><h2 id="Read-in-this-order" tabindex="-1">Read in this order <a class="header-anchor" href="#Read-in-this-order" aria-label="Permalink to &quot;Read in this order {#Read-in-this-order}&quot;">​</a></h2><ol><li><p><a href="./distributions-reactant">Distribution kernels through Reactant</a> — scalar, structured, and batched boundaries.</p></li><li><p><a href="./eight-schools-reactant">Eight Schools through Reactant</a> — reviewed PPL primal and value-and-gradient evidence.</p></li><li><p><a href="./mnist-reactant">MNIST through Reactant</a> — reviewed full-data model evidence.</p></li><li><p><a href="./reactant-ad">AD + Reactant</a> — the compiled prepared-AD API and its limits.</p></li></ol><p>Older throughput and experimental sampling receipts appear afterward. They are not promoted into the reviewed capability set, and sampling compiler/runtime code is not executed by the docs build.</p><h2 id="Current-boundary" tabindex="-1">Current boundary <a class="header-anchor" href="#Current-boundary" aria-label="Permalink to &quot;Current boundary {#Current-boundary}&quot;">​</a></h2><ul><li><p>Prepared scalar kernels and tensorized distribution plates are accepted.</p></li><li><p>Every plate keeps the batched or broadcast lowering whatever its lane count: a lane count is a data length, so no plate is unrolled into per-lane scalar recipes (see <a href="./constraints">core constraints</a>). The automatic AD compile keeps bound arrays of at most 4096 elements embedded as compiler literals.</p></li><li><p>Authored <code>if</code>, <code>?:</code>, <code>&amp;&amp;</code> and <code>||</code> keep their lazy Julia semantics: the tensorized companion lowers them to <code>stablehlo.if</code> regions (also inside a batched plate cell), so an inactive side is never evaluated or differentiated. <code>Base.ifelse</code> remains an eager select of two already valid values. See <a href="./constraints">core constraints</a>.</p></li><li><p>An authored <code>for</code>/<code>while</code> inside a recipe keeps its iteration: the tensorized companion expands it with <code>ReactantCore.@trace</code> at kernel definition, so it becomes one <code>stablehlo.while</code> region whatever the trip count; the loop body is never replicated per iteration.</p></li><li><p>A traced Cholesky factorization is a wrapper type owned by the Reactant extension, with <code>LinearAlgebra.Cholesky</code>&#39;s accessors (<code>.L</code>, <code>.U</code>, <code>.UL</code>, <code>.factors</code>) and solves (<code>\\</code>, <code>ldiv!</code>; a diagonal factor divides elementwise). A Cholesky passed as state, a factorization stored into compiled reactive state, and a <code>cholesky(...)</code> call inside a larger <code>@kernel</code> expression (<code>cholesky(Symmetric(K)).L</code>) produce it; the extension defines no methods on Reactant&#39;s own factorization type, which has no <code>.L</code>/<code>.U</code>. Within one kernel call, a <code>cholesky</code> call outside that lowering — in a helper function the kernel calls, or a statement that is exactly <code>F = cholesky(A)</code> — yields Reactant&#39;s type, whose packed factor is <code>F.factors</code>.</p></li><li><p>Whole-kernel <code>replica</code> preserves the scalar kernel as its source authority.</p></li><li><p>Compiled AD reuses the native single-active-port, scalar-WANT validation.</p></li><li><p>Unsupported scalar indexing, unbounded control, or structural state rejects; the docs do not paper over those errors with alternate implementations.</p></li><li><p>NUTS/WALNUTS pages are source- and receipt-only during documentation builds.</p></li></ul>',8)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
